<template><view class="phone"><PageHeader title="消息中心" back/><ConnectionState/><view class="padded-content"><view class="section-row"><text class="section-title">{{unreadCount}} 条未读</text><button class="text-button" @click="markAllRead">全部已读</button></view><text class="block muted small">消息随订单和报修同步；已读状态仅保存在当前设备，按登录账号区分。</text><view v-for="message in messages" :key="message.id" class="panel message-card" @click="open(message)"><view class="section-row"><text class="section-title">{{message.title}}</text><text v-if="!preferences.read.includes(message.id)" class="tag">未读</text></view><text class="block">{{message.body}}</text><text class="block muted small">{{message.time?new Date(message.time).toLocaleString():'时间未提供'}} ›</text></view><view v-if="!messages.length" class="empty-state">暂无消息<text>充电进展和报修反馈会在这里显示</text></view></view></view></template>
<script setup>
import {onShow} from '@dcloudio/uni-app';import PageHeader from '../../components/PageHeader.vue';import ConnectionState from '../../components/ConnectionState.vue';import {refreshData,go} from '../../store.js';import {messages,unreadCount,preferences,markRead,markAllRead} from '../../user-preferences.js';
onShow(()=>refreshData());function open(message){markRead(message.id);go(message.path);}
</script>
<style scoped>.message-card{margin-top:16px;line-height:1.8}.message-card .small{margin-top:10px}</style>
